<?php
require '../inc/db.php';session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();header('Content-Type: application/json');
$fail=static function($message,$code=422){http_response_code($code);echo json_encode(['ok'=>false,'error'=>$message]);exit;};
if($_SERVER['REQUEST_METHOD']!=='POST')$fail('Invalid request method.',405);if(!hash_equals($_SESSION['public_csrf']??'',(string)($_POST['csrf']??'')))$fail('Checkout expired. Reload your order page and try again.');
$ref=(string)($_POST['ref']??'');if($ref===''||!hash_equals((string)($_SESSION['ref']??''),$ref))$fail('This order cannot be updated from this session.',403);
try{$pdo=db();$s=$pdo->prepare("SELECT id,payment,payment_status FROM orders WHERE ref=? LIMIT 1");$s->execute([$ref]);$order=$s->fetch();if(!$order||$order['payment']!=='transfer')$fail('This order is not awaiting bank transfer.');$pdo->prepare("UPDATE orders SET payment_status=CASE WHEN payment_status IN('unpaid','failed') THEN 'customer_marked_paid' ELSE payment_status END,payment_done_at=COALESCE(payment_done_at,NOW()) WHERE id=?")->execute([$order['id']]);echo json_encode(['ok'=>true]);}catch(Throwable $x){error_log('Payment confirmation click could not be saved: '.$x->getMessage());$fail('We could not save your payment confirmation. Please retry before opening WhatsApp.',500);}
